-- Additive migration. Existing member, wallet, order and funding data are not modified.
BEGIN;
CREATE TABLE IF NOT EXISTS km_organizations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),type TEXT NOT NULL CHECK(type IN ('HQ','SUB_HQ','AGENT')),name TEXT NOT NULL,parent_id UUID REFERENCES km_organizations(id),status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED')),created_by UUID REFERENCES km_users(id),created_at TIMESTAMPTZ DEFAULT NOW(),CHECK ((type='HQ' AND parent_id IS NULL) OR (type<>'HQ' AND parent_id IS NOT NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS km_org_one_hq ON km_organizations(type) WHERE type='HQ';
CREATE INDEX IF NOT EXISTS km_org_parent ON km_organizations(parent_id);
CREATE TABLE IF NOT EXISTS km_organization_members(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organization_id UUID NOT NULL REFERENCES km_organizations(id),user_id UUID NOT NULL UNIQUE REFERENCES km_users(id),role TEXT NOT NULL CHECK(role IN ('SUB_HQ','AGENT')),status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS km_referral_codes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),code TEXT NOT NULL UNIQUE,agent_id UUID NOT NULL REFERENCES km_users(id),organization_id UUID NOT NULL REFERENCES km_organizations(id),status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','DISABLED')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS km_member_attributions(user_id UUID PRIMARY KEY REFERENCES km_users(id),agent_id UUID REFERENCES km_users(id),sub_hq_id UUID REFERENCES km_organizations(id),organization_id UUID NOT NULL REFERENCES km_organizations(id),referral_code_id UUID REFERENCES km_referral_codes(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS km_attr_agent ON km_member_attributions(agent_id);
CREATE INDEX IF NOT EXISTS km_attr_subhq ON km_member_attributions(sub_hq_id);
CREATE TABLE IF NOT EXISTS km_org_permissions(key TEXT PRIMARY KEY,allowed_roles TEXT[] NOT NULL,delegable BOOLEAN NOT NULL,risk_level TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS km_permission_grants(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),subject_id UUID NOT NULL REFERENCES km_organizations(id),permission_key TEXT NOT NULL REFERENCES km_org_permissions(key),granted_by UUID NOT NULL REFERENCES km_users(id),granted_status TEXT NOT NULL CHECK(granted_status IN ('ACTIVE','REVOKED')),can_delegate BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(subject_id,permission_key));
CREATE TABLE IF NOT EXISTS km_permission_change_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_id UUID NOT NULL REFERENCES km_users(id),subject_id UUID NOT NULL REFERENCES km_organizations(id),permission_key TEXT NOT NULL,old_value JSONB,new_value JSONB NOT NULL,reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS km_management_audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_id UUID REFERENCES km_users(id),target_id UUID,action TEXT NOT NULL,before_data JSONB,after_data JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS km_member_attribution_history(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES km_users(id),previous_org UUID REFERENCES km_organizations(id),next_org UUID NOT NULL REFERENCES km_organizations(id),actor_id UUID REFERENCES km_users(id),reason TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
INSERT INTO km_organizations(id,type,name) VALUES('00000000-0000-4000-8000-000000000001','HQ','K-MARKETS 본사') ON CONFLICT DO NOTHING;
COMMIT;
